{
  "hypotheses": [
    {
      "cause": "容器状态异常",
      "predictions": {
        "ops.containers": ["exited"]
      },
      "because": [
        "容器状态为 exited，表明应用进程已终止，可能导致订单业务异常。"
      ]
    },
    {
      "cause": "路由版本不一致",
      "predictions": {
        "ops.route_status": ["v2"]
      },
      "because": [
        "路由版本为 v2，可能与预期版本不一致，导致服务不可达或性能下降。"
      ]
    },
    {
      "cause": "应用不可达",
      "predictions": {
        "application.status": ["unreachable"]
      },
      "because": [
        "应用直接可达性为 unreachable，表明应用服务可能已中断或存在网络问题。"
      ]
    },
    {
      "cause": "数据库读写分离",
      "predictions": {
        "db.read_only_status": ["ro"]
      },
      "because": [
        "数据库处于 read-only 模式，可能影响订单业务的写入操作，导致业务异常。"
      ]
    },
    {
      "cause": "数据库阻塞会话",
      "predictions": {
        "db.blocking_sessions": ["blocked"]
      },
      "because": [
        "存在数据库阻塞会话，可能影响订单业务的并发处理能力，导致业务异常。"
      ]
    }
  ]
}

